<template><section class="section container dashboard-page"><div class="toolbar"><div><div class="eyebrow">Ruang redaksi</div><h1>Kelola berita</h1><p class="muted">Atur naskah, thumbnail, dan status publikasi.</p></div><NuxtLink class="btn btn-primary" to="/admin/berita/create">+ Berita baru</NuxtLink></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Preview</th><th>Judul</th><th>Status</th><th>Penulis</th><th>Aksi</th></tr></thead><tbody><tr v-for="item in store.list" :key="item.id"><td><img v-if="item.thumbnail" class="table-thumb" :src="imageUrl(item.thumbnail)" :alt="item.judul"><span v-else class="table-thumb placeholder">--</span></td><td><strong>{{ item.judul }}</strong><div class="meta">{{ item.kategori_nama || 'Umum' }}</div></td><td><span class="status" :class="`status-${item.status}`">{{ item.status }}</span></td><td>{{ item.penulis }}</td><td><div class="actions"><NuxtLink class="btn btn-quiet" :to="`/admin/berita/edit-${item.id}`">Edit</NuxtLink><button class="btn btn-danger" @click="remove(item.id)">Hapus</button></div></td></tr></tbody></table></div></section></template><script setup lang="ts">definePageMeta({middleware:'admin'});const store=useBeritaStore();const config=useRuntimeConfig();const imageUrl=(path:string)=>`${config.public.uploadsBase}${path}`;await store.fetchAll({limit:50,status:''});async function remove(id:number){if(confirm('Hapus berita ini?')){await store.remove(id);await store.fetchAll({limit:50,status:''})}}</script>
